-- ============================================================
-- Quiz coverage for databases/sql, devops/linux, data/excel --
-- Overview through Advanced (or through the deepest tab that
-- exists, for Linux, which has no separate advanced.md).
--
-- devops/linux/overview and data/excel/overview already have 5
-- questions each from docs/sample-quiz-questions.sql -- not
-- repeated here. Run after that file (or in any order; ON CONFLICT
-- DO NOTHING makes both idempotent regardless of run order).
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- databases/sql/overview ----------
('databases', 'sql', 'overview', 'Which SQL command category does SELECT belong to?', '["DDL", "DML", "DQL", "DCL"]', 2, 'SELECT is Data Query Language (DQL) -- it retrieves data without changing structure (DDL) or modifying rows (DML).', 'beginner'),
('databases', 'sql', 'overview', 'Why is BIGSERIAL/TIMESTAMPTZ in a CREATE TABLE example specifically a PostgreSQL detail, not universal SQL?', '["They are deprecated everywhere", "MySQL and SQL Server use different auto-increment/timestamp syntax (AUTO_INCREMENT/IDENTITY, different date types)", "They only work in SQLite", "They require a paid license"]', 1, 'SERIAL/BIGSERIAL and TIMESTAMPTZ are PostgreSQL-specific -- MySQL uses AUTO_INCREMENT, SQL Server uses IDENTITY, with different type names throughout.', 'beginner'),
('databases', 'sql', 'overview', 'WHERE filters rows before grouping. What filters groups after a GROUP BY?', '["ORDER BY", "HAVING", "LIMIT", "DISTINCT"]', 1, 'HAVING filters on aggregated group results (like COUNT or AVG of a group); WHERE cannot reference aggregate functions.', 'beginner'),
('databases', 'sql', 'overview', 'In MySQL, what is the correct INTERVAL syntax for "30 days ago"?', '["INTERVAL ''30 days''", "INTERVAL 30 DAY", "INTERVAL(30, DAY)", "DAYS(30)"]', 1, 'MySQL uses INTERVAL 30 DAY with no quotes; the quoted ''30 days'' form is PostgreSQL syntax specifically.', 'intermediate'),
('databases', 'sql', 'overview', 'Why does GROUP BY matter for query correctness, not just formatting?', '["It only affects the sort order", "It determines which rows get combined into a single summarized row before aggregate functions apply", "It is purely cosmetic and can always be omitted", "It replaces the need for WHERE entirely"]', 1, 'GROUP BY collapses rows sharing the same value(s) into one row per group -- aggregate functions (SUM, COUNT, AVG) then compute per-group, which is fundamentally different from filtering individual rows.', 'beginner'),

-- ---------- databases/sql/fundamentals ----------
('databases', 'sql', 'fundamentals', 'A table has a NOT NULL constraint on `department_id`. What happens if you try to INSERT a row without providing that column and no DEFAULT is set?', '["The row inserts with department_id as NULL", "The insert fails with a constraint violation", "The row inserts with department_id as 0", "Nothing -- NOT NULL is only enforced on UPDATE"]', 1, 'NOT NULL constraints are enforced on INSERT -- without a DEFAULT, omitting a NOT NULL column with no default causes the insert to fail.', 'beginner'),
('databases', 'sql', 'fundamentals', 'Why does a correlated subquery typically cost more than an independent (uncorrelated) subquery on a large table?', '["It always returns more rows", "It conceptually re-evaluates once per row of the outer query, since it references an outer-query column", "It can only use INNER JOIN", "It cannot use aggregate functions"]', 1, 'A correlated subquery references a column from the outer query, so its logic depends on the current outer row -- the database effectively has to consider it per outer row, unlike an independent subquery that runs once regardless of outer row count.', 'intermediate'),
('databases', 'sql', 'fundamentals', 'A NOT IN subquery unexpectedly returns zero rows even though you expect matches. What is the most likely cause?', '["The table has too many rows", "The subquery result set contains a NULL value, making the whole NOT IN comparison indeterminate", "NOT IN is deprecated and no longer works", "The outer query is missing a WHERE clause"]', 1, 'If the subquery inside NOT IN returns even one NULL, SQL''s three-valued logic makes the entire comparison UNKNOWN for every row, silently returning zero rows instead of an error.', 'intermediate'),
('databases', 'sql', 'fundamentals', 'Which is the safer alternative to NOT IN when the subquery might return NULLs?', '["UNION", "NOT EXISTS", "GROUP BY", "HAVING"]', 1, 'NOT EXISTS does not have the NULL-poisoning failure mode that NOT IN has, and is often faster on large tables too.', 'intermediate'),
('databases', 'sql', 'fundamentals', 'Why must every NOT NULL column be included when using PostgREST/Supabase-style upsert() against a table with other NOT NULL columns, even for rows that already exist?', '["Upsert always creates a brand new table", "Postgres validates NOT NULL constraints on the tentative row before ON CONFLICT resolution applies, so missing columns default to NULL and fail the constraint", "NOT NULL only applies to the first INSERT ever", "It is a client library bug, not a database behavior"]', 1, 'Confirmed via direct testing: Postgres builds and validates the tentative row (including NOT NULL checks) before the ON CONFLICT DO UPDATE path takes over -- omitted NOT NULL columns default to NULL and fail, regardless of whether the row already exists.', 'advanced'),

-- ---------- databases/sql/intermediate ----------
('databases', 'sql', 'intermediate', 'What is the key difference between RANK() and DENSE_RANK() when there is a tie?', '["They behave identically in every case", "RANK leaves a gap in numbering after a tie; DENSE_RANK does not", "DENSE_RANK only works with numeric columns", "RANK cannot be used with PARTITION BY"]', 1, 'After a tie, RANK skips ahead by the number of tied rows (e.g. 1,1,3), while DENSE_RANK continues consecutively (1,1,2) -- DENSE_RANK is the one typically wanted for "Nth highest distinct value" queries.', 'intermediate'),
('databases', 'sql', 'intermediate', 'Why does a MySQL CREATE FUNCTION with a BEGIN...END body need a DELIMITER change before it will actually run via a client?', '["MySQL functions are deprecated", "The semicolons inside BEGIN...END would otherwise be read as statement terminators by the client before the CREATE FUNCTION statement completes", "DELIMITER changes the function''s return type", "It is only needed for stored procedures, never functions"]', 1, 'Without changing the delimiter (e.g. to // ), the client sends everything up to the first semicolon as a complete statement -- cutting the function definition off mid-body.', 'advanced'),
('databases', 'sql', 'intermediate', 'A MySQL query uses SUM(sale_date < ''2019-01-01'') to count matching rows. Why does the equivalent fail on PostgreSQL?', '["PostgreSQL does not support SUM at all", "PostgreSQL does not implicitly coerce booleans to integers inside SUM() the way MySQL does -- it needs an explicit CASE WHEN", "PostgreSQL requires dates to be quoted differently", "SUM only works with GROUP BY in PostgreSQL"]', 1, 'MySQL implicitly treats a boolean expression as 1/0 inside SUM(); PostgreSQL does not, and raises "function sum(boolean) does not exist" without an explicit CASE WHEN ... THEN 1 ELSE 0 END.', 'advanced'),
('databases', 'sql', 'intermediate', 'Why is WITH RECURSIVE written differently across engines for the same recursive-hierarchy query?', '["Recursion is impossible in SQL Server", "SQL Server infers recursion from query structure and treats the RECURSIVE keyword itself as a syntax error, unlike PostgreSQL/MySQL 8+/SQLite which require it", "RECURSIVE only works with numeric primary keys", "It is purely a stylistic choice with no functional difference"]', 1, 'PostgreSQL, MySQL 8+, and SQLite require the RECURSIVE keyword; SQL Server infers recursion automatically and rejects RECURSIVE as invalid syntax.', 'advanced'),
('databases', 'sql', 'intermediate', 'What does EXISTS/NOT EXISTS check, fundamentally, compared to IN/NOT IN?', '["Whether a column value falls within a numeric range", "Whether the subquery returns at least one row, without caring about the actual returned values", "Whether a table has any rows at all", "Whether an index exists on the table"]', 1, 'EXISTS just checks for row presence (typically with SELECT 1 inside), which is why it is immune to the NULL-poisoning problem that plagues NOT IN -- it never compares against the subquery''s actual values.', 'intermediate'),

-- ---------- databases/sql/advanced ----------
('databases', 'sql', 'advanced', 'Why does `SELECT * FROM emp WHERE ROWNUM <= 3 ORDER BY salary DESC` NOT reliably return the top 3 salaries in Oracle?', '["ROWNUM only works with numeric columns", "ROWNUM is assigned to rows BEFORE the ORDER BY in the same query is applied, so it filters arbitrary rows first, then sorts just those", "ORDER BY DESC is invalid syntax in Oracle", "ROWNUM can only be used in an UPDATE statement"]', 1, 'ROWNUM is assigned during row retrieval, before ORDER BY takes effect within that same query block -- the correct pattern wraps the ordered query in a subquery, applying ROWNUM only in the outer query.', 'advanced'),
('databases', 'sql', 'advanced', 'What is the correct pattern to reliably get the "top N rows by some order" in Oracle using ROWNUM?', '["Apply ROWNUM and ORDER BY in the same flat query", "Wrap an already-ORDER-BY''d query in a subquery, then apply the ROWNUM filter in the outer query", "ROWNUM cannot be combined with ORDER BY under any circumstances", "Use LIMIT instead of ROWNUM"]', 1, 'SELECT * FROM (SELECT * FROM t ORDER BY col DESC) WHERE ROWNUM <= N -- the ordering must happen in the inner query, with ROWNUM filtering applied afterward on the already-sorted result.', 'advanced'),
('databases', 'sql', 'advanced', 'What real production problem does wrapping an indexed column in a function, like WHERE YEAR(created_at) = 2024, actually cause?', '["It has no real performance effect", "It prevents the database from using any index on that column, forcing a full table scan regardless of indexing", "It only affects INSERT performance, not SELECT", "It causes a syntax error on most engines"]', 1, 'The database must compute YEAR() for every row before it can evaluate the filter, which defeats the index entirely -- rewriting as a range comparison (created_at >= ''2024-01-01'' AND created_at < ''2025-01-01'') lets the index be used directly.', 'advanced'),
('databases', 'sql', 'advanced', 'Why is `DELETE p1 FROM Person p1, Person p2 WHERE p1.Email = p2.Email AND p1.Id > p2.Id;` not portable to PostgreSQL or SQL Server?', '["DELETE statements do not exist in those engines", "This comma-join multi-table DELETE syntax is MySQL-specific; other engines need a subquery-based approach instead", "Email columns cannot be compared for equality in PostgreSQL", "Id columns must be UUIDs in SQL Server"]', 1, 'MySQL''s multi-table DELETE with comma-joined tables has no standard-SQL equivalent -- PostgreSQL/SQL Server need something like DELETE FROM Person WHERE Id NOT IN (SELECT MIN(Id) FROM Person GROUP BY Email).', 'advanced'),
('databases', 'sql', 'advanced', 'A dashboard shows slightly different revenue numbers depending on the exact moment a MySQL query runs against an actively-written table, using a CTE. What is the most likely explanation?', '["MySQL CTEs are always broken and should never be used", "MySQL''s CTE handling has historically behaved more like a view, potentially re-evaluating the underlying query multiple times within one execution, unlike PostgreSQL which materializes by default", "The dashboard has a caching bug unrelated to SQL", "CTEs cannot read from tables under active writes at all"]', 1, 'PostgreSQL materializes a CTE once by default (a fixed snapshot); MySQL has historically re-evaluated CTEs more like a view, which can pick up different data mid-execution under concurrent writes.', 'advanced'),

-- ---------- devops/linux/fundamentals ----------
('devops', 'linux', 'fundamentals', 'Which command do you run BEFORE `apt install` or `yum install` to confirm which distro family a server belongs to?', '["uname -r", "cat /etc/os-release", "df -h", "ps aux"]', 1, '/etc/os-release identifies the distro and family (Debian/Ubuntu vs RHEL-family) -- running the wrong package manager against the wrong family is a common, avoidable mistake.', 'beginner'),
('devops', 'linux', 'fundamentals', 'What does the SUID bit (chmod u+s) actually do when set on an executable?', '["Lets any user delete the file", "Makes the program run with the FILE OWNER''s privileges, regardless of who invokes it", "Prevents the file from ever being modified", "Compresses the file automatically"]', 1, 'SUID is exactly how a regular user can run `passwd` to change their own password despite needing root access to /etc/shadow -- it runs as the file''s owner, not the invoking user.', 'intermediate'),
('devops', 'linux', 'fundamentals', 'Why should systemctl be preferred over the older `service` command on a modern Linux distribution?', '["service is faster", "service is a legacy compatibility shim on systemd systems and does not expose systemd''s actual state/dependency information directly", "service only works for network-related services", "systemctl requires no privileges at all"]', 1, 'On systemd-based systems, `service` is a compatibility wrapper -- `systemctl` talks to systemd directly and exposes real state/dependency info.', 'beginner'),
('devops', 'linux', 'fundamentals', 'What is the practical difference between /proc and /etc?', '["They are identical, just different names", "/etc holds real, persistent configuration files on disk; /proc is a virtual filesystem exposing live kernel/process state, not real files", "/proc is where user home directories live", "/etc is only used by systemd"]', 1, 'Writing to certain /proc entries changes live kernel behavior immediately -- /proc/sys are virtual, kernel-generated views, not data stored on disk the way /etc configuration files are.', 'beginner'),
('devops', 'linux', 'fundamentals', 'A command like `sudo apt install nginx` needs sudo. Which of these commands from the same workflow does NOT need sudo?', '["systemctl start nginx", "systemctl status nginx", "useradd -m -s /bin/bash deploy", "chown user:group file.txt"]', 1, '`systemctl status` is a read-only view of a service''s current state -- it does not modify anything, unlike start/stop/enable or file ownership changes.', 'beginner'),

-- ---------- devops/linux/intermediate ----------
('devops', 'linux', 'intermediate', 'Why is `vmstat` typically the right FIRST command to run when a server "feels slow"?', '["It shows disk space only", "It surfaces both CPU saturation (the r column) and memory pressure (si/so swap columns) in one glance, before diving into resource-specific tools", "It automatically fixes performance issues", "It only works on RHEL-family distros"]', 1, 'vmstat gives a fast, single-glance read on two of the four USE-method resources (CPU, memory) before you commit to a deeper, resource-specific investigation.', 'intermediate'),
('devops', 'linux', 'intermediate', 'What does a real, growing CLOSE-WAIT connection count in `ss`/`netstat` output usually indicate?', '["Normal, healthy connection closing behavior", "An application-level bug: the app is not closing connections it should be -- a genuine resource leak", "The server has run out of disk space", "A DNS resolution failure"]', 1, 'Unlike TIME-WAIT (which is a normal part of a connection finishing its close sequence), a growing CLOSE-WAIT count points to the application itself failing to close connections -- worth investigating in app code, not the OS.', 'intermediate'),
('devops', 'linux', 'intermediate', 'In `set -euo pipefail`, what specifically does the -o pipefail option change about a pipeline''s reported exit status?', '["It makes the pipeline always report success", "Without it, only the LAST command''s exit code counts; with it, the pipeline reports the rightmost non-zero exit status among all commands in it", "It disables pipes entirely", "It only applies to pipelines with exactly two commands"]', 1, 'Without pipefail, `cmd_that_fails | cmd_that_succeeds` reports success since only the last command counts by default -- pipefail surfaces a failure from any stage, reporting the rightmost non-zero code specifically (not the first failing command).', 'advanced'),
('devops', 'linux', 'intermediate', 'Why does `for f in $files; do rm $f; done` break on filenames containing spaces, even if $files is a correctly-populated variable?', '["rm cannot delete files with spaces in their names under any circumstance", "Unquoted variable expansion undergoes word-splitting, so a value with a space gets treated as multiple separate arguments", "for loops cannot iterate more than once", "$files must be declared as an integer"]', 1, 'Without quotes, the shell splits on whitespace during expansion -- a single filename with a space becomes two separate loop iterations/arguments instead of one.', 'intermediate'),
('devops', 'linux', 'intermediate', 'Why does journalctl -u <service> often find logs that grep-ing /var/log won''t?', '["journalctl only works for network services", "Logs for systemd-managed services often live in the binary journal store, not as a plain text file under /var/log at all", "grep cannot search files larger than 1GB", "journalctl requires no privileges while /var/log always does"]', 1, 'For anything running as a systemd service, journalctl -u <service> is the right first command -- the journal is often the actual source of truth, not a flat text file grep can search directly.', 'intermediate'),

-- ---------- data/excel/fundamentals ----------
('data', 'excel', 'fundamentals', 'Why is XLOOKUP generally safer to use than VLOOKUP when columns might be inserted into a table later?', '["XLOOKUP is faster to type", "VLOOKUP relies on a fixed column-index number that shifts when columns are inserted; XLOOKUP references the return column directly", "XLOOKUP only works with numbers", "VLOOKUP cannot be used in a Table at all"]', 1, 'VLOOKUP''s col_index_num silently points to the wrong column if a column is inserted earlier in the range; XLOOKUP avoids this entirely by referencing the return array/column directly.', 'beginner'),
('data', 'excel', 'fundamentals', 'What does the IFERROR function actually do?', '["Prevents a formula from ever producing a wrong result", "Returns a specified fallback value if the wrapped formula would otherwise return an error", "Automatically fixes the underlying data", "Only works with VLOOKUP specifically"]', 1, 'IFERROR(formula, fallback) catches any error the inner formula would produce (like #N/A from a failed lookup) and substitutes your specified fallback instead.', 'beginner'),
('data', 'excel', 'fundamentals', 'In a HAVING clause equivalent for Excel (e.g. filtering PivotTable groups), what is the key difference from a plain filter on raw rows?', '["There is no difference", "A group-level filter applies after aggregation (e.g. only show categories where SUM > 1000), not to individual raw rows", "Group filters only work with COUNT", "PivotTables cannot filter at all"]', 1, 'Filtering on an aggregated value (a category''s total) is conceptually different from filtering individual transaction rows -- this is the same WHERE-vs-HAVING distinction that shows up in SQL.', 'intermediate'),
('data', 'excel', 'fundamentals', 'Why does Find & Replace (Ctrl+H) not support "*$" as "anything ending in a currency symbol" the way a regex engine would?', '["Find & Replace is broken in current Excel", "Find & Replace does plain substring matching by default -- * and $ are not treated as wildcard/anchor characters there", "Only VBA can do text replacement in Excel", "$ is reserved and cannot appear in any Excel formula"]', 1, 'Excel''s standard Find & Replace dialog is literal substring matching, not a regex engine -- to strip a currency symbol you replace the literal character itself (e.g. replace "$" with "").', 'intermediate'),
('data', 'excel', 'fundamentals', 'What is the main advantage of converting a data range into a real Excel Table (Ctrl+T) before building formulas and PivotTables on it?', '["Tables look nicer with alternating row colors, nothing else", "Formulas and PivotTables built on a Table auto-expand as new rows are added, without needing to manually update range references", "Tables are required before any formula will work", "Tables automatically remove duplicate rows"]', 1, 'A Table''s structured references and auto-expanding range mean formulas and PivotTables stay correct as data grows -- a plain range requires manually re-selecting the range every time rows are added.', 'beginner'),

-- ---------- data/excel/intermediate ----------
('data', 'excel', 'intermediate', 'In XLOOKUP''s optional search_mode argument, what real risk does setting it to 2 (binary search, ascending) introduce?', '["No risk -- binary search is always safe to use", "It silently returns WRONG results if the lookup column is not actually sorted ascending", "It makes the formula recalculate slower on every keystroke", "It disables the if_not_found argument"]', 1, 'Binary search assumes sorted data -- if the lookup column (e.g. Products[SKU]) is not genuinely sorted ascending, XLOOKUP with search_mode 2 can return the wrong row with no error at all.', 'advanced'),
('data', 'excel', 'intermediate', 'What does the LET function let you do that a series of separate helper-column formulas does not?', '["Nothing different -- LET is purely cosmetic", "Name intermediate calculation results within a single formula, improving readability without needing separate helper cells", "Run VBA code from inside a formula", "Automatically fix circular references"]', 1, 'LET(name, value, calculation) lets you define named intermediate values inline within one formula -- useful when the same sub-calculation is needed multiple times within that formula.', 'intermediate'),
('data', 'excel', 'intermediate', 'What determines whether an array formula needs Ctrl+Shift+Enter in Excel?', '["All array formulas always need it, regardless of version", "Only in pre-365 (legacy) Excel -- Excel 365''s dynamic arrays spill automatically on plain Enter", "Only formulas containing SUM need it", "It depends on the user''s keyboard layout"]', 1, 'Excel 365 introduced dynamic arrays that spill automatically -- Ctrl+Shift+Enter is only required for legacy array formulas in pre-365 versions.', 'intermediate'),
('data', 'excel', 'intermediate', 'Why might a Power Query M-code custom function be preferred over a repeated manual transformation step?', '["M-code always runs faster than any formula", "The same transformation logic can be reused and reapplied consistently every time the query refreshes, rather than being redone by hand", "Custom functions are required before Power Query will import any data", "M-code cannot reference other queries"]', 1, 'A defined custom function in Power Query is reusable and automatically reapplied on every refresh -- consistent, repeatable transformation instead of manual, error-prone repetition.', 'advanced'),
('data', 'excel', 'intermediate', 'What is a genuine risk of a SUMIFS formula that references a plain cell range instead of a Table''s structured reference, as new data is added?', '["SUMIFS cannot use ranges at all, only Tables", "The plain range does not auto-expand, so newly added rows silently fall outside the criteria/sum ranges unless manually updated", "Structured references are slower to calculate", "SUMIFS with structured references cannot use date criteria"]', 1, 'A hardcoded range like A2:A100 does not grow when row 101 is added -- a Table-based structured reference (SalesData[Amount]) expands automatically, so the formula keeps including new data without manual maintenance.', 'intermediate'),

-- ---------- data/excel/advanced ----------
('data', 'excel', 'advanced', 'In VBA, what is the practical difference between using `=` and `Set` when assigning a value to a variable?', '["They are interchangeable in every case", "Set is required specifically when assigning an OBJECT (like a Worksheet or Range) to a variable; = is for plain values", "Set only works inside a Function, never a Sub", "= is used only for numeric variables"]', 1, 'Using = instead of Set on an object assignment (or vice versa on a plain value) is a very common first-week VBA error -- object references need Set, values use =.', 'intermediate'),
('data', 'excel', 'advanced', 'Why does `ws.Cells(ws.Rows.Count, "A").End(xlUp).Row` reliably find the last used row in column A, even as data grows or shrinks?', '["It always returns a hardcoded row number", "It starts from the very bottom of the sheet and works upward until hitting the first non-empty cell, adapting automatically to the actual data size", "It only works if the sheet has fewer than 100 rows", "It requires the data to already be sorted"]', 1, 'This is the standard VBA idiom for finding the true last row -- more reliable than a hardcoded row number that breaks the moment the underlying data grows or shrinks.', 'advanced'),
('data', 'excel', 'advanced', 'What must a workbook be saved as in order to keep VBA macros functional?', '[".xlsx", ".xlsm", ".csv", ".pdf"]', 1, 'Saving as plain .xlsx silently strips all VBA code -- macro-enabled workbooks must be saved as .xlsm (or .xlsb for the binary format).', 'beginner'),
('data', 'excel', 'advanced', 'What is the fastest way to learn VBA object-model syntax (Range, Worksheet, Font) without memorizing it from scratch?', '["Read the entire VBA language specification first", "Developer tab -> Record Macro, perform the action manually, then inspect the generated code in the VBA editor", "VBA cannot be learned without a formal course", "Copy random code from forums without understanding it"]', 1, 'Recording a macro while performing an action manually generates real, working VBA code using the actual object model -- reading that output is a practical way to learn Range/Worksheet/Font syntax before writing VBA from scratch.', 'beginner'),
('data', 'excel', 'advanced', 'In `FormatConditions.Add(xlCellValue, xlLess, 0)`, what does this conditional formatting rule actually do?', '["Highlights cells greater than 0", "Adds a rule that formats cells whose value is less than 0", "Deletes all existing conditional formatting", "Only applies to text values, never numbers"]', 1, 'xlCellValue/xlLess/0 defines a cell-value-based rule matching values less than 0 -- exactly the "flag negative values" pattern used to automate formatting that would otherwise be reapplied by hand every month.', 'advanced')

ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
